(function(){
  'use strict';
  const contractToday=()=>new Date().toISOString().slice(0,10);
  const contractId=()=>typeof uid==='function'?uid():`contract-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
  const contractDateAfter=days=>{const date=new Date();date.setDate(date.getDate()+days);return date.toISOString().slice(0,10)};
  const defaultContractBody=()=>`This Client Services Agreement confirms the scope, deliverables, timelines, fees, and responsibilities agreed by Eric's Designs and the client.\n\nServices and deliverables\nThe services listed in the linked quotation form part of this agreement. Changes to the agreed scope must be approved in writing.\n\nFees and payment\nA 50% advance is required before work begins. The remaining balance is due on completion, unless the linked quotation states otherwise.\n\nTimeline and approvals\nThe work starts after this agreement and the advance are confirmed. Timelines depend on timely client feedback, content, and approvals.\n\nConfidentiality\nBoth parties will keep project information and client material confidential, except where disclosure is required to deliver the agreed work.\n\nAcceptance\nBy confirming this contract, both parties accept the linked quotation and the terms above.`;
  const contractState=()=>{
    db.contracts=Array.isArray(db.contracts)?db.contracts:[];
    db.contractTemplates=Array.isArray(db.contractTemplates)?db.contractTemplates:[];
    return db;
  };
  const clientForContract=contract=>db.clients.find(client=>client.id===contract.clientId)||{name:contract.clientName||'Client'};
  const quoteForContract=contract=>db.documents.find(document=>document.id===contract.quotationId);
  const contractStatusBadge=status=>`<span class="badge ${status==='Confirmed'?'Paid':status==='Ready'?'Sent':'Draft'}">${esc(status||'Draft')}</span>`;
  const contractTemplateOptions=(selected='')=>`<option value="">Start without a template</option>${db.contractTemplates.map(template=>`<option value="${template.id}" ${template.id===selected?'selected':''}>${esc(template.name)}</option>`).join('')}`;
  const contractClientOptions=(selected='')=>`<option value="">Select a client</option>${db.clients.map(client=>`<option value="${client.id}" ${client.id===selected?'selected':''}>${esc(client.name)}</option>`).join('')}`;
  const contractQuotationOptions=(selected='')=>`<option value="">No quotation linked</option>${db.documents.filter(document=>document.type==='Quotation'&&document.status!=='Cancelled').map(document=>`<option value="${document.id}" ${document.id===selected?'selected':''}>${esc(document.number)} · ${esc(document.client?.name||'Client')} · ${esc(document.project||'Quotation')}</option>`).join('')}`;
  const contractDetails=contract=>{
    const client=clientForContract(contract),quote=quoteForContract(contract);
    return `<section class="panel contract-detail"><div class="dialog-title"><div><div class="eyebrow">CLIENT CONTRACT</div><h2>${esc(contract.title||contract.project||'Client contract')}</h2><p class="sub">${esc(client.name)}${quote?` · ${esc(quote.number)}`:''}</p></div><div class="actions"><button onclick="editClientContract('${contract.id}')">Edit contract</button><button onclick="saveContractAsTemplate('${contract.id}')">Save as template</button></div></div><div class="stats three"><div class="stat"><span>Status</span><strong>${esc(contract.status||'Draft')}</strong><small>Update this when the agreement is confirmed.</small></div><div class="stat"><span>Start date</span><strong>${esc(contract.startDate||'—')}</strong><small>Expected completion: ${esc(contract.completionDate||'—')}</small></div><div class="stat"><span>Linked quotation</span><strong>${esc(quote?.number||'—')}</strong><small>${quote?esc(quote.project||'Quotation'):'No quotation linked'}</small></div></div><section class="contract-paper"><div class="contract-paper-head"><span>ERIC'S DESIGNS</span><b>CLIENT SERVICES AGREEMENT</b></div><h3>${esc(contract.title||'Client Services Agreement')}</h3><p><b>Client:</b> ${esc(client.name)}${contract.signatory?` · ${esc(contract.signatory)}`:''}</p><p><b>Project:</b> ${esc(contract.project||quote?.project||'—')}</p><div class="contract-body">${esc(contract.body||'').replace(/\n/g,'<br>')}</div>${contract.notes?`<div class="contract-notes"><b>Notes</b><br>${esc(contract.notes).replace(/\n/g,'<br>')}</div>`:''}<div class="contract-signatures"><div><b>For Eric's Designs</b><span>${esc(contract.confirmedBy||'Pending confirmation')}</span></div><div><b>For the client</b><span>${esc(contract.signatory||client.name||'Pending confirmation')}</span></div></div></section></section>`;
  };
  window.contractsWorkspace=function(){
    contractState();
    const contracts=[...db.contracts].sort((a,b)=>String(b.updated||b.created||'').localeCompare(String(a.updated||a.created||'')));
    return pageHeader('Client contracts.',`<button onclick="editClientContract()">+ New contract</button><button class="primary" onclick="editContractTemplate()">+ New template</button>`,'Create agreements after a quotation is approved, edit the wording for each client, and reuse your saved contract templates.')+
      `<section class="panel"><div class="dialog-title"><div><div class="eyebrow">CONTRACTS</div><h2>Client agreements</h2></div><span class="counts">${contracts.length} saved</span></div>${contracts.length?`<div class="contract-list">${contracts.map(contract=>{const client=clientForContract(contract),quote=quoteForContract(contract);return `<article class="contract-row"><div><b>${esc(contract.title||contract.project||'Client contract')}</b><small>${esc(client.name)} · ${esc(quote?.number||'No quotation linked')} · Updated ${esc(String(contract.updated||contract.created||'').slice(0,10)||'—')}</small></div>${contractStatusBadge(contract.status)}<div class="actions"><button class="smallbtn" onclick="openClientContract('${contract.id}')">Open</button><button class="smallbtn" onclick="editClientContract('${contract.id}')">Edit</button></div></article>`}).join('')}</div>`:'<div class="empty"><h2>No client contracts yet.</h2><p>Create a contract directly, or open Client Process after an approved quotation.</p><button class="primary" onclick="editClientContract()">Create contract</button></div>'}</section>`+
      `<section class="panel"><div class="dialog-title"><div><div class="eyebrow">SAVED TEMPLATES</div><h2>Reusable contract wording</h2></div><button class="smallbtn" onclick="editContractTemplate()">+ Template</button></div>${db.contractTemplates.length?`<div class="contract-template-grid">${db.contractTemplates.map(template=>`<article class="contract-template-card"><h3>${esc(template.name)}</h3><p>${esc(template.title||'Client Services Agreement')}</p><small>${num(template.defaultDays||30)} day default completion period</small><div class="actions"><button class="smallbtn" onclick="newClientContractFromTemplate('${template.id}')">Use template</button><button class="smallbtn" onclick="editContractTemplate('${template.id}')">Edit</button></div></article>`).join('')}</div>`:'<p class="sub">Save your first reusable contract template for future projects.</p>'}</section>`;
  };
  window.openClientContract=function(id){selectedClientContract=id;navClick('Contracts');};
  window.newClientContract=function(quotationId=''){ selectedClientContract=''; editClientContract(null,quotationId); };
  window.newClientContractFromTemplate=function(templateId){ selectedClientContract=''; editClientContract(null,'',templateId); };
  window.editClientContract=function(id='',quotationId='',templateId=''){
    contractState();
    const existing=db.contracts.find(item=>item.id===id);
    const quote=db.documents.find(document=>document.id===(quotationId||existing?.quotationId));
    const template=db.contractTemplates.find(item=>item.id===(templateId||existing?.templateId));
    const client=db.clients.find(item=>item.id===(existing?.clientId||quote?.client?.id))||db.clients.find(item=>item.name===quote?.client?.name);
    const record=structuredClone(existing||{id:contractId(),clientId:client?.id||'',clientName:client?.name||quote?.client?.name||'',quotationId:quote?.id||'',templateId:template?.id||'',title:template?.title||'Client Services Agreement',project:quote?.project||'',status:'Draft',signatory:quote?.client?.contact||client?.contact||client?.name||'',confirmedBy:'',startDate:contractToday(),completionDate:contractDateAfter(num(template?.defaultDays)||30),body:template?.body||defaultContractBody(),notes:template?.notes||'',created:new Date().toISOString(),updated:new Date().toISOString()});
    recordDraft=record;
    modal(existing?'Edit client contract':'New client contract',`<div><label for="contract-client">Client *</label><select id="contract-client">${contractClientOptions(record.clientId)}</select></div><div><label for="contract-quotation">Approved quotation</label><select id="contract-quotation">${contractQuotationOptions(record.quotationId)}</select></div><div><label for="contract-status">Contract status</label><select id="contract-status">${['Draft','Ready','Confirmed'].map(status=>`<option ${record.status===status?'selected':''}>${status}</option>`).join('')}</select></div><div><label for="contract-template">Template reference</label><select id="contract-template">${contractTemplateOptions(record.templateId)}</select></div><div class="full"><label for="contract-title">Contract title *</label><input id="contract-title" value="${esc(record.title)}" required></div><div class="full"><label for="contract-project">Project / subject</label><input id="contract-project" value="${esc(record.project)}"></div><div><label for="contract-signatory">Client signatory *</label><input id="contract-signatory" value="${esc(record.signatory)}" required></div><div><label for="contract-confirmed-by">Confirmed by (Eric's Designs)</label><input id="contract-confirmed-by" value="${esc(record.confirmedBy)}" placeholder="Name when confirmed"></div><div><label for="contract-start">Start date *</label><input id="contract-start" type="date" value="${esc(record.startDate)}" required></div><div><label for="contract-completion">Expected completion</label><input id="contract-completion" type="date" value="${esc(record.completionDate)}"></div><div class="full"><label for="contract-body">Agreement text *</label><textarea id="contract-body" style="min-height:320px">${esc(record.body)}</textarea></div><div class="full"><label for="contract-notes">Internal notes</label><textarea id="contract-notes">${esc(record.notes)}</textarea></div><p class="hint full">Marking this contract Confirmed unlocks the 50% advance proforma and delivery setup for its linked quotation.</p>`,()=>{
      const clientId=val('contract-client'),quotationIdValue=val('contract-quotation'),linkedQuote=db.documents.find(document=>document.id===quotationIdValue),linkedClient=db.clients.find(item=>item.id===clientId)||db.clients.find(item=>item.name===linkedQuote?.client?.name);
      const next={...record,clientId:linkedClient?.id||clientId,clientName:linkedClient?.name||linkedQuote?.client?.name||'',quotationId:quotationIdValue,templateId:val('contract-template'),title:val('contract-title').trim(),project:val('contract-project').trim(),status:val('contract-status'),signatory:val('contract-signatory').trim(),confirmedBy:val('contract-confirmed-by').trim(),startDate:val('contract-start'),completionDate:val('contract-completion'),body:val('contract-body').trim(),notes:val('contract-notes').trim(),updated:new Date().toISOString()};
      if(!next.clientId||!next.title||!next.signatory||!next.startDate||!next.body){document.getElementById('recordError').textContent='Choose a client and complete the required contract details.';return}
      if(next.completionDate&&next.completionDate<next.startDate){document.getElementById('recordError').textContent='Completion date must be on or after the start date.';return}
      if(commitChange(()=>{const index=db.contracts.findIndex(item=>item.id===next.id);index<0?db.contracts.push(next):db.contracts.splice(index,1,next);if(next.status==='Confirmed'&&linkedQuote){linkedQuote.contract={acceptedBy:next.signatory,startDate:next.startDate,completionDate:next.completionDate,scope:next.project||next.title,contractId:next.id};linkedQuote.contractConfirmedAt=next.updated;linkedQuote.clientApprovedForProcess=true;linkedQuote.updated=next.updated;if(window.ClientProcessEngine)ClientProcessEngine.prepare(db,linkedQuote,uid)}},`${existing?'Updated':'Created'} contract ${next.title}`)){closeSaved();selectedClientContract=next.id;nav('Contracts')}});
  };
  window.saveContractAsTemplate=function(id){const contract=db.contracts.find(item=>item.id===id);if(!contract)return;modal('Save contract as template',field('Template name *','contract-template-name',contract.title||'Client Services Agreement','text','required')+field('Default completion days','contract-template-days',Math.max(1,Math.round((new Date(contract.completionDate||contract.startDate)-new Date(contract.startDate||contractToday()))/86400000)||30),'number','required min="1" max="365"')+`<div class="full"><label for="contract-template-notes">Template notes</label><textarea id="contract-template-notes">${esc(contract.notes||'')}</textarea></div>`,()=>{const name=val('contract-template-name').trim(),days=num(val('contract-template-days'));if(!name||days<1){document.getElementById('recordError').textContent='Add a template name and completion period.';return}const template={id:contractId(),name,title:contract.title,body:contract.body,notes:val('contract-template-notes').trim(),defaultDays:days,created:new Date().toISOString(),updated:new Date().toISOString()};if(commitChange(()=>db.contractTemplates.push(template),`Saved contract template ${name}`))closeSaved()}); };
  window.editContractTemplate=function(id=''){
    contractState();const found=db.contractTemplates.find(item=>item.id===id),template=structuredClone(found||{id:contractId(),name:'',title:'Client Services Agreement',body:defaultContractBody(),notes:'',defaultDays:30,created:new Date().toISOString(),updated:new Date().toISOString()});recordDraft=template;
    modal(found?'Edit contract template':'New contract template',field('Template name *','contract-template-name',template.name,'text','required')+field('Default contract title *','contract-template-title',template.title,'text','required')+field('Default completion days','contract-template-days',template.defaultDays,'number','required min="1" max="365"')+`<div class="full"><label for="contract-template-body">Agreement text *</label><textarea id="contract-template-body" style="min-height:320px">${esc(template.body)}</textarea></div><div class="full"><label for="contract-template-notes">Internal template notes</label><textarea id="contract-template-notes">${esc(template.notes)}</textarea></div>`,()=>{const next={...template,name:val('contract-template-name').trim(),title:val('contract-template-title').trim(),defaultDays:num(val('contract-template-days')),body:val('contract-template-body').trim(),notes:val('contract-template-notes').trim(),updated:new Date().toISOString()};if(!next.name||!next.title||!next.body||next.defaultDays<1){document.getElementById('recordError').textContent='Complete the template name, title, text, and completion period.';return}if(commitChange(()=>{const index=db.contractTemplates.findIndex(item=>item.id===next.id);index<0?db.contractTemplates.push(next):db.contractTemplates.splice(index,1,next)},`${found?'Updated':'Created'} contract template ${next.name}`))closeSaved()});
  };
  const migrateBeforeContracts=migrate;
  migrate=function(data){const result=migrateBeforeContracts(data);result.contracts=Array.isArray(result.contracts)?result.contracts.filter(item=>item&&typeof item==='object'):[];result.contractTemplates=Array.isArray(result.contractTemplates)?result.contractTemplates.filter(item=>item&&typeof item==='object'):[];return result;};
  migrate(db); let selectedClientContract='';
  const renderBeforeContracts=render;
  render=function(){renderBeforeContracts();if(view==='Contracts'&&!draft){const contract=db.contracts.find(item=>item.id===selectedClientContract);document.getElementById('app').innerHTML=contract?contractDetails(contract):contractsWorkspace();}const nav=document.getElementById('nav');if(nav&&!nav.querySelector('[title="Contracts"]')){const anchor=nav.querySelector('[title="Templates"]')||nav.lastChild;const button=document.createElement('button');button.title='Contracts';button.className=view==='Contracts'?'active':'';button.innerHTML='<span class="nav-icon">§</span><span class="nav-label">Contracts</span>';button.onclick=()=>{selectedClientContract='';navClick('Contracts')};if(anchor)anchor.before(button);else nav.append(button)}};
  const navClick=window.nav; window.nav=function(next){if(next==='Contracts')selectedClientContract='';return navClick(next)};
  window.processContract=function(quotationId){newClientContract(quotationId);};
  try{if(Array.isArray(HORIZONTAL_MORE_SECTIONS)&&!HORIZONTAL_MORE_SECTIONS.includes('Contracts'))HORIZONTAL_MORE_SECTIONS.push('Contracts');if(Array.isArray(HORIZONTAL_MORE_GROUPS)&&HORIZONTAL_MORE_GROUPS[1]&&!HORIZONTAL_MORE_GROUPS[1].items.includes('Contracts'))HORIZONTAL_MORE_GROUPS[1].items.push('Contracts');}catch{}
})();
